package fr.mavoixecrite;
import android.app.*;import android.content.*;import android.view.View;import android.widget.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,35})
public class TraceTest {
 Context context;
 @Before public void reset(){context=RuntimeEnvironment.getApplication();for(String n:new String[]{DataFile.NAME,DataFile.NAME+".new","phrases-v2.json"})new File(context.getFilesDir(),n).delete();for(String n:new String[]{"options","draft","MainActivity","conversation","voice"})context.getSharedPreferences(n,0).edit().clear().commit();context.getSharedPreferences("options",0).edit().putBoolean("correct",false).commit();}
 AppTest.FakeSpeech fake(MainActivity a){a.speech.close();AppTest.FakeSpeech f=new AppTest.FakeSpeech(a);a.speech=f;return f;}
 String trace(MainActivity a){return ((TextView)a.findViewById(R.id.trace_message)).getText().toString();}
 @Test public void selectionIsVisibleEvenWithoutVoiceStart()throws Exception{try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();fake(a);AppTest.find(a.getWindow().getDecorView(),"Merci").performClick();assertEquals("Merci",trace(a));assertEquals(View.VISIBLE,a.findViewById(R.id.trace_panel).getVisibility());assertTrue(new PhraseStore(context).history().isEmpty());}}
 @Test public void traceSurvivesFamilyChangeAndRecreationWithoutReplacingDraft(){try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();fake(a);((EditText)a.findViewById(R.id.message_input)).setText("Je prépare ma réponse");AppTest.find(a.getWindow().getDecorView(),"Oui").performClick();AppTest.find(a.getWindow().getDecorView(),"Besoins").performClick();assertEquals("Oui",trace(a));ctl.recreate();a=ctl.get();assertEquals("Oui",trace(a));assertEquals("Je prépare ma réponse",((EditText)a.findViewById(R.id.message_input)).getText().toString());}}
 @Test public void hidingDoesNotEraseDraftOrRepeat(){try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();AppTest.FakeSpeech f=fake(a);AppTest.find(a.getWindow().getDecorView(),"Merci").performClick();f.whenStarted.run();((EditText)a.findViewById(R.id.message_input)).setText("À garder");AppTest.find(a.getWindow().getDecorView(),"Masquer").performClick();assertEquals(View.GONE,a.findViewById(R.id.trace_panel).getVisibility());AppTest.find(a.getWindow().getDecorView(),"Répéter").performClick();assertEquals("Merci",f.spoken);assertEquals("À garder",((EditText)a.findViewById(R.id.message_input)).getText().toString());}}
 @Test public void enlargeUsesSelectedMessage(){try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();fake(a);((EditText)a.findViewById(R.id.message_input)).setText("Un autre brouillon");AppTest.find(a.getWindow().getDecorView(),"Non").performClick();AppTest.find(a.getWindow().getDecorView(),"Agrandir").performClick();Intent i=Shadows.shadowOf(a).getNextStartedActivity();assertEquals("Non",i.getStringExtra("message"));}}
 @Test public void keyboardKeepsSpaceForWriting(){try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();fake(a);AppTest.find(a.getWindow().getDecorView(),"Merci").performClick();a.onImeVisibility(true);assertEquals(View.GONE,a.findViewById(R.id.trace_panel).getVisibility());a.onImeVisibility(false);assertEquals(View.VISIBLE,a.findViewById(R.id.trace_panel).getVisibility());assertEquals("Merci",trace(a));}}
 @Test public void interlocutorAnswerBecomesLastVisibleMessage(){Intent i=new Intent(context,DisplayActivity.class).putExtra("message","Bonjour").putExtra("interlocutor",true);try(ActivityController<DisplayActivity> ctl=Robolectric.buildActivity(DisplayActivity.class,i).setup()){AppTest.find(ctl.get().getWindow().getDecorView(),"Non").performClick();assertEquals("Non",context.getSharedPreferences("conversation",0).getString("trace",""));}}
}
